package com.yuegang.zhihui.ai.api;import com.yuegang.zhihui.ai.application.*;import com.yuegang.zhihui.ai.security.*;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.common.web.*;import jakarta.servlet.http.*;import jakarta.validation.*;import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/admin/ai")public final class AiGovernanceController{private final AiGovernanceService service;private final AiUserResolver users;public AiGovernanceController(AiGovernanceService s,AiUserResolver u){service=s;users=u;}@GetMapping("/prompts")ApiResponse<List<PromptConfigView>>prompts(HttpServletRequest r){users.require(r,"ai:prompt:read");return ok(service.prompts(),r);}@PostMapping("/prompts")ApiResponse<PromptConfigView>save(@Valid @RequestBody SavePromptConfigRequest b,HttpServletRequest r){return ok(service.save(b,users.require(r,"ai:prompt:write")),r);}@GetMapping("/evaluation-cases")ApiResponse<List<EvaluationCaseView>>cases(HttpServletRequest r){users.require(r,"ai:evaluation:read");return ok(service.cases(),r);}@PostMapping("/evaluation-cases")ApiResponse<EvaluationCaseView>add(@Valid @RequestBody SaveEvaluationCaseRequest b,HttpServletRequest r){return ok(service.addCase(b,users.require(r,"ai:evaluation:write")),r);}private static<T>ApiResponse<T>ok(T x,HttpServletRequest r){return ApiResponse.success(x,TraceIdResolver.resolve(r));}}
